import React, { useState, useEffect } from 'react';
import { UserRole, User, Produce, Order, OrderStatus } from './types';
import { MOCK_PRODUCE, MOCK_ORDERS } from './constants';
import Layout from './components/Layout';
import FarmerDashboard from './components/FarmerDashboard';
import BuyerMarketplace from './components/BuyerMarketplace';
import DeliveryPortal from './components/DeliveryPortal';
import { Leaf, UserCircle, Truck, ShoppingBag } from 'lucide-react';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [produce, setProduce] = useState<Produce[]>(MOCK_PRODUCE);
  const [orders, setOrders] = useState<Order[]>(MOCK_ORDERS);

  // Persistence (Simulation)
  useEffect(() => {
    const savedProduce = localStorage.getItem('agro_produce');
    const savedOrders = localStorage.getItem('agro_orders');
    if (savedProduce) setProduce(JSON.parse(savedProduce));
    if (savedOrders) setOrders(JSON.parse(savedOrders));
  }, []);

  useEffect(() => {
    localStorage.setItem('agro_produce', JSON.stringify(produce));
    localStorage.setItem('agro_orders', JSON.stringify(orders));
  }, [produce, orders]);

  const handleLogin = (role: UserRole) => {
    const names = {
      [UserRole.FARMER]: 'Samuel Farmer',
      [UserRole.BUYER]: 'Jane Buyer',
      [UserRole.DELIVERY]: 'Dave Delivery'
    };
    const ids = {
      [UserRole.FARMER]: 'f1',
      [UserRole.BUYER]: 'b1',
      [UserRole.DELIVERY]: 'd1'
    };
    setCurrentUser({
      id: ids[role],
      name: names[role],
      role: role,
      location: 'Regional Hub'
    });
  };

  const addProduce = (newProduce: Partial<Produce>) => {
    if (!currentUser) return;
    const p: Produce = {
      id: `p-${Date.now()}`,
      farmerId: currentUser.id,
      farmerName: currentUser.name,
      name: newProduce.name || '',
      category: newProduce.category || 'Vegetables',
      quantity: newProduce.quantity || 0,
      pricePerKg: newProduce.pricePerKg || 0,
      yieldDate: newProduce.yieldDate || '',
      expireDate: newProduce.expireDate || '',
      location: newProduce.location || '',
      description: newProduce.description,
      image: newProduce.image || 'https://picsum.photos/400/300'
    };
    setProduce(prev => [p, ...prev]);
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    setOrders(prev => prev.map(o => o.id === orderId ? { 
      ...o, 
      status, 
      deliveryId: status === OrderStatus.IN_TRANSIT ? currentUser?.id : o.deliveryId 
    } : o));
  };

  const placeOrder = (o: Partial<Order>) => {
    const newOrder: Order = {
      id: `o-${Date.now()}`,
      produceId: o.produceId!,
      produceName: o.produceName!,
      buyerId: o.buyerId!,
      buyerName: o.buyerName!,
      farmerId: o.farmerId!,
      quantity: o.quantity!,
      totalProducePrice: o.totalProducePrice!,
      transportationCost: o.transportationCost!,
      distance: o.distance!,
      pickupLocation: o.pickupLocation!,
      deliveryLocation: o.deliveryLocation!,
      status: o.status!,
      createdAt: new Date().toISOString()
    };
    setOrders(prev => [newOrder, ...prev]);

    // Deduct quantity from produce
    setProduce(prev => prev.map(p => p.id === o.produceId ? { ...p, quantity: p.quantity - o.quantity! } : p));
  };

  if (!currentUser) {
    return (
      <div className="min-h-screen bg-emerald-50 flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-md space-y-8 text-center">
          <div className="flex flex-col items-center gap-3">
            <div className="p-4 bg-white rounded-3xl shadow-xl shadow-emerald-100">
              <Leaf className="h-16 w-16 text-emerald-600" />
            </div>
            <h1 className="text-4xl font-black text-slate-800 tracking-tight">AgroChain</h1>
            <p className="text-slate-600">Secure, Direct Farm-to-Table Marketplace</p>
          </div>

          <div className="bg-white p-8 rounded-[2rem] shadow-2xl shadow-emerald-200 border border-emerald-100 space-y-6">
            <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">Select Your Role</p>
            <div className="grid grid-cols-1 gap-4">
              <button 
                onClick={() => handleLogin(UserRole.FARMER)}
                className="group flex items-center justify-between p-4 rounded-2xl border-2 border-slate-100 hover:border-emerald-500 hover:bg-emerald-50 transition-all text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-emerald-100 rounded-xl group-hover:bg-emerald-600 group-hover:text-white transition-colors">
                    <UserCircle className="h-6 w-6" />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">I am a Farmer</h3>
                    <p className="text-xs text-slate-500">List produce and manage orders</p>
                  </div>
                </div>
              </button>

              <button 
                onClick={() => handleLogin(UserRole.BUYER)}
                className="group flex items-center justify-between p-4 rounded-2xl border-2 border-slate-100 hover:border-blue-500 hover:bg-blue-50 transition-all text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-blue-100 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-colors">
                    <ShoppingBag className="h-6 w-6" />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">I am a Buyer</h3>
                    <p className="text-xs text-slate-500">Browse and purchase fresh produce</p>
                  </div>
                </div>
              </button>

              <button 
                onClick={() => handleLogin(UserRole.DELIVERY)}
                className="group flex items-center justify-between p-4 rounded-2xl border-2 border-slate-100 hover:border-amber-500 hover:bg-amber-50 transition-all text-left"
              >
                <div className="flex items-center gap-4">
                  <div className="p-3 bg-amber-100 rounded-xl group-hover:bg-amber-600 group-hover:text-white transition-colors">
                    <Truck className="h-6 w-6" />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-800">I am a Delivery Partner</h3>
                    <p className="text-xs text-slate-500">Accept contracts and earn per trip</p>
                  </div>
                </div>
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      role={currentUser.role} 
      userName={currentUser.name} 
      onLogout={() => setCurrentUser(null)}
    >
      {currentUser.role === UserRole.FARMER && (
        <FarmerDashboard 
          produce={produce.filter(p => p.farmerId === currentUser.id)}
          orders={orders.filter(o => o.farmerId === currentUser.id)}
          onAddProduce={addProduce}
          onUpdateOrderStatus={updateOrderStatus}
        />
      )}

      {currentUser.role === UserRole.BUYER && (
        <BuyerMarketplace 
          produce={produce.filter(p => p.quantity > 0)}
          orders={orders}
          onPlaceOrder={placeOrder}
          buyerName={currentUser.name}
          buyerId={currentUser.id}
        />
      )}

      {currentUser.role === UserRole.DELIVERY && (
        <DeliveryPortal 
          orders={orders}
          onAcceptDelivery={(id) => updateOrderStatus(id, OrderStatus.IN_TRANSIT)}
          onCompleteDelivery={(id) => updateOrderStatus(id, OrderStatus.DELIVERED)}
          deliveryId={currentUser.id}
        />
      )}
    </Layout>
  );
};

export default App;
